# owner: platform
"""Seating rows for a class."""

from typing import List

from rosterkit.models import Student


def _sort_key(student: Student) -> tuple:
    return (student.last_name.lower(), student.first_name.lower())


def _row_line(number: int, row: List[Student]) -> str:
    names = " | ".join(item.display_name for item in row)
    return f"Row {number}: {names}"


# ---
def seating_rows(students: List[Student], seats: int):
    """Return one text line per row, sorted by last name."""
    if seats < 1 or not students:
        raise ValueError("need students and a positive seat count")
    ordered = sorted(students, key=_sort_key)
    rows = [ordered[pos:pos + seats]
            for pos in range(0, len(ordered), seats)]
    return [_row_line(num, row) for num, row in enumerate(rows, 1)]
EOF
cat > tests/test_seating.py <<'EOF'
import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows


def make(last, first):
    return Student(last + first, last, first, "A")


class SeatingTests(unittest.TestCase):
    def test_sorted_and_split_into_rows(self):
        people = [
            make("Halloway", "Juno"),
            make("Dunmere", "Piet"),
            make("Abbott", "Cara")
        ]
        self.assertEqual(
            seating_rows(people, 2),
            [
                "Row 1: Abbott, Cara | Dunmere, Piet",
                "Row 2: Halloway, Juno"
            ]
        )

    def test_bad_seat_count_raises(self):
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seating_rows([make("Dunmere", "Piet")], seats)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
EOF
